inline else => |colors| {
return client.throw(globalThis, signature, Output.prettyFmt((("\n\n" ++ fmt) ++ "\n"), colors), .{ expected.toFmt((&formatter.val)), list_formatter, successful_returns_count });
},
}
        }
}
